import hashlib


class _Rules(Rules):
    """ObservationNoise (O axis, harder with DOSE): corrupt a deterministic fraction DOSE of the
    observation text by swapping characters in the grid/state rendering, without touching the
    underlying world. bucket = sha256(f"{task_id}:{step}")[:8] % 10000; corrupted iff bucket < DOSE*10000,
    so the corrupted step set is nested in DOSE. Solvable by construction (world untouched)."""

    DOSE = 0.75
    TASK_ID = '1'

    def _corrupted(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._corrupted(env_state):
            return obs
        text = obs.text
        chars = list(text)
        for i in range(len(chars)):
            if chars[i].isdigit():
                chars[i] = str((int(chars[i]) + 1) % 10)
        return Observation(text="".join(chars), data=obs.data)

import hashlib


class _Rules(Rules):
    """CommandSwap (O axis, harder with DOSE): corrupt the admissible-commands list by
    swapping a deterministic fraction DOSE of commands with near-miss strings. The world is
    untouched and the true command text remains recoverable by position/context, so the task
    stays solvable."""

    DOSE = 0.5
    TASK_ID = '23'

    def _perturbed(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}:swap".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def _swap(self, cmd):
        if cmd and cmd[0].islower():
            return cmd[0].upper() + cmd[1:]
        if cmd and cmd[0].isupper():
            return cmd[0].lower() + cmd[1:]
        return cmd

    def filter_observation(self, obs, env_state):
        if not self._perturbed(env_state):
            return obs
        data = dict(obs.data or {})
        cmds = data.get("admissible_commands")
        if isinstance(cmds, list) and cmds:
            data["admissible_commands"] = [self._swap(c) if isinstance(c, str) else c for c in cmds]
        return Observation(text=obs.text, data=data)
